        vm.assume(extraAmount <= type(uint128).max);

        address actor = makeAddr("user");
        vm.deal(actor, creditAmount + extraAmount);

        // Deposit the credit amount as a different user so actor has a clean state
        vm.prank(address(0xdead));
        c.deposit{value: 1}();

        // Actor deposits creditAmount
        vm.prank(actor);
        c.deposit{value: creditAmount}();

        // Optionally deposit some extra by the same actor to have balance > creditAmount
        vm.prank(actor);
        c.deposit{value: extraAmount}();

        uint256 balBefore = address(c).balance;
        uint256 creditBefore = creditAmount; // actor only deposited creditAmount (extraAmount goes to balance but not actor's credit)

        vm.prank(actor);
        c.withdrawAll();

        uint256 balAfter = address(c).balance;
        uint256 creditAfter = 0; // credit is private, no getter, but we can infer zero credit from repeated withdrawAll revert or lack of payable call success; we instead use the invariant that balance decreased equals old credit.

        // INVARIANT: balance reduction equals creditBefore, which ensures credit is fully zeroed and balance tracks correctly.
        // The bug decreases balance by creditBefore - 1, so reduction < creditBefore.
        assertTrue(balBefore - balAfter == creditBefore);
    }
}

