pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 attackerSeed) public {
        // Restrict deposit to a reasonable range to avoid overflow and keep balance manageable
        vm.assume(depositAmount > 0 && depositAmount <= 100 ether);
        // Create attacker and helper actors
        address attacker = address(uint160(uint256(keccak256(abi.encode(attackerSeed)))));
        vm.assume(attacker != address(0) && attacker != address(this));

        // Give attacker ETH and deposit
        vm.deal(attacker, depositAmount);
        vm.prank(attacker);
        c.deposit{value: depositAmount}();

        // Deploy a malicious reentrant contract that attempts to double-dip
        Reenter exploiter = new Reenter(address(c));
        vm.deal(address(exploiter), 1 ether); // for gas if needed

        // Initial credit of attacker
        uint256 initialCredit = c.credit(attacker);
        uint256 initialBalance = address(c).balance;

        // The exploiter deposits once to have legitimate credit
        vm.prank(address(exploiter));
        c.deposit{value: 1 ether}();

        uint256 exploiterCredit = c.credit(address(exploiter));

        // Attempt a withdrawAll via the reentrant contract
        vm.prank(address(exploiter));
        exploiter.attack();

        // After the call, check invariant: contract balance >= sum of all recorded credits
        // We iterate over potential actors? No getter for mapping, but we know attacker and exploiter.
        // Universal invariant: address(c).balance >= sum(known credits); for any single actor, credit <= balance.
        // Better: After all calls, the contract's ETH balance + total amount ever withdrawn must equal total deposited.
        // Since we can't sum mapping without iterating, we assert a direct observable invariant:
        // The exploiter's credit after attack must be <= contract balance (obvious but always true).
        // Actually, the invariant that breaks: after withdrawAll, credit must be 0 if call didn't revert.
        // We assert that if exploiter's credit is non-zero, balance must be at least that credit; otherwise,
        // the bug allows balance to drop below credit.
        uint256 finalBalance = address(c).balance;
        uint256 finalAttackerCredit = c.credit(attacker);
        uint256 finalExploiterCredit = c.credit(address(exploiter));

        // The general rule: The sum of all credits (attacker + exploiter) must be <= contract balance.
        // The bug allows a reentrant withdrawAll to zero credit early and drain extra ETH,
        // so finalBalance < (finalAttackerCredit + finalExploiterCredit).
        assertTrue(finalBalance >= finalAttackerCredit + finalExploiterCredit);
    }
}

contract Reenter {
    C target;
    bool reentered;
    constructor(address _target) { target = C(_target); }

    function attack() external {
        target.withdrawAll();
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            target.withdrawAll();
        }
    }
}

