pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 deposit0, uint256 deposit1, uint256 withdrawAmount) public {
        // Keep amounts within a reasonable range, but wide enough for the fuzzer to find the bug
        deposit0 = bound(deposit0, 1, 1_000_000 ether);
        deposit1 = bound(deposit1, 1, 1_000_000 ether);
        withdrawAmount = bound(withdrawAmount, 1, 1_000_000 ether);
        address actor = address(uint160(uint256(keccak256(abi.encode(deposit0, deposit1, withdrawAmount)))));
        vm.assume(actor != address(this) && actor != address(0));

        // Deposit some amount to actor
        vm.deal(actor, deposit0);
        vm.prank(actor);
        c.deposit{value: deposit0}();

        // Another deposit from this contract (can be anyone, just to add some balance)
        vm.deal(address(this), deposit1);
        c.deposit{value: deposit1}();

        // Determine how much actor can actually withdraw (min of deposit0 and withdrawAmount)
        uint256 actorCredit = c.credit(actor);
        uint256 actualWithdraw = actorCredit < withdrawAmount ? actorCredit : withdrawAmount;
        vm.assume(actualWithdraw > 0);

        // Withdraw a portion of actor's credit
        vm.prank(actor);
        try c.withdrawAll() {} catch {}

        // After withdrawal, contract's ETH balance must be <= sum of all credits
        // (In the reference contract, balance == total credits; in the mutant, balance > total credits after withdrawal)
        uint256 contractBalance = address(c).balance;
        uint256 totalCredits = c.credit(actor) + c.credit(address(this));
        assertTrue(contractBalance <= totalCredits);
    }
}

